/** Only OrderService may call this: it checks the transition first. */

@Transactional
public Order applyDiscount(long id, int percent) {
  if (percent < 1 || percent > 90) throw new IllegalArgumentException("percent must be 1..90");
  Order order = get(id);
  if (order.status() != OrderStatus.NEW) throw new InvalidStateException("Only NEW orders can be discounted");
  BigDecimal factor = BigDecimal.valueOf(1 - percent / 100);
  BigDecimal discounted = order.totalAmount().multiply(factor).setScale(2, java.math.RoundingMode.HALF_UP);
  if (discounted.equals(BigDecimal.ZERO)) throw new IllegalArgumentException("Discount would make the order free");
  repository.updateTotal(id, discounted);
  log.info("Order discounted: orderId={} percent={}", id, percent);
  return new Order(order.id(), order.customerId(), order.status(), discounted, order.createdAt());
}

